import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.YKbyQ3zk.js";const u=JSON.parse('{"title":"Quickstart: TanStack Start with Convex","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart/tanstack-convex.md","filePath":"quickstart/tanstack-convex.md"}'),n={name:"quickstart/tanstack-convex.md"};function i(d,e,r,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="quickstart-tanstack-start-with-convex" tabindex="-1">Quickstart: TanStack Start with Convex <a class="header-anchor" href="#quickstart-tanstack-start-with-convex" aria-label="Permalink to &quot;Quickstart: TanStack Start with Convex&quot;">​</a></h1><p>This page takes you from an empty folder to a TanStack Start app on Convex where you sign up with an email address and a password and land on a signed-in page. Convex runs on your machine, so you need no Convex account, no mail service and no OAuth app.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Node and pnpm.</strong> Use the Node version your Convex release supports; the <a href="./../supported-versions.html">supported versions</a> page lists what was tested.</li><li><strong>git.</strong> <code>init</code> refuses to run in a folder that is not a git repository, because it checks that git ignores the file it writes your secrets to.</li></ul><p>The commands below are for a Unix shell (macOS, Linux, or WSL). Run each block as a whole. Steps 8 and 9 each need their own terminal, so keep this one for the rest.</p><p>Step 2 installs from the npm registry, so it works once Evo Auth has been published there.</p><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><h3 id="1-create-the-app" tabindex="-1">1. Create the app <a class="header-anchor" href="#1-create-the-app" aria-label="Permalink to &quot;1. Create the app&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm create @tanstack/start@0.59.61 my-app --yes</span></span>
<span class="line"><span>cd my-app</span></span>
<span class="line"><span>test -d .git || git init</span></span></code></pre></div><p><code>--yes</code> accepts the create command&#39;s defaults and asks nothing. The create command may end with a line saying <code>@tanstack/intent install</code> did not run successfully: ignore it. The last line starts a git repository only if the create command did not.</p><h3 id="2-install-the-packages" tabindex="-1">2. Install the packages <a class="header-anchor" href="#2-install-the-packages" aria-label="Permalink to &quot;2. Install the packages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm add convex@1.49.0 @evo-auth/core@0.1.0 @evo-auth/react@0.1.0 @evo-auth/convex@0.1.0</span></span></code></pre></div><h3 id="3-make-the-local-convex-deployment" tabindex="-1">3. Make the local Convex deployment <a class="header-anchor" href="#3-make-the-local-convex-deployment" aria-label="Permalink to &quot;3. Make the local Convex deployment&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>npx convex dev --once</span></span></code></pre></div><p>Convex asks <code>Would you like to login to your account?</code>: choose <code>Start without an account (run Convex locally)</code>, then answer <code>Continue?</code> with Enter (yes). It then makes a deployment on your machine, writes <code>VITE_CONVEX_URL</code> and <code>VITE_CONVEX_SITE_URL</code> into <code>.env.local</code>, and exits. <code>init</code> needs this deployment, because it sets the auth variables on it.</p><h3 id="4-run-init" tabindex="-1">4. Run init <a class="header-anchor" href="#4-run-init" aria-label="Permalink to &quot;4. Run init&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm exec evo-auth init --stack tanstack-convex</span></span></code></pre></div><p><code>init</code> writes these files and refuses, changing nothing, if any of them already exists:</p><ul><li><code>.env.local</code> gets the signing keys and secrets it made. No other file holds a secret.</li><li><code>evo-auth.config.ts</code>: email and password sign-up, no provider, and a development sender that prints each code in the <code>npx convex dev</code> terminal instead of sending mail.</li><li><code>convex/convex.config.ts</code>, <code>convex/auth.config.ts</code>, <code>convex/http.ts</code> and <code>convex/auth.ts</code>: the Evo Auth component, its routes and its email job.</li><li><code>src/lib/evo-auth.server.ts</code> and <code>src/routes/auth/$.ts</code>: the proxy that relays <code>/auth/*</code> from your app to Convex.</li><li><code>src/middleware/evo-auth.ts</code>, and <code>src/start.ts</code> if your app has none. If your app already has a <code>src/start.ts</code>, <code>init</code> prints the one line to add to it.</li><li><code>src/components/evo-auth-root.tsx</code>, with the Convex provider inside it, and <code>src/routes/sign-in.tsx</code> and <code>src/routes/sign-up.tsx</code>.</li></ul><p>It then sets the auth variables on your local deployment with <code>npx convex env set</code>, and prints the edits it does not make itself. Steps 5 to 7 are those edits.</p><h3 id="5-import-the-root-component" tabindex="-1">5. Import the root component <a class="header-anchor" href="#5-import-the-root-component" aria-label="Permalink to &quot;5. Import the root component&quot;">​</a></h3><p>In <code>src/routes/__root.tsx</code>, add this line with the other imports:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;">import</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> loadAuthState </span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">}</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> from</span><span style="--shiki-light:#17723F;--shiki-dark:#7FD6A4;"> &quot;../components/evo-auth-root&quot;</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">;</span></span></code></pre></div><h3 id="6-add-the-loader" tabindex="-1">6. Add the loader <a class="header-anchor" href="#6-add-the-loader" aria-label="Permalink to &quot;6. Add the loader&quot;">​</a></h3><p>In the same file, add these two lines to the options object that <code>createRootRoute</code> is called with, beside <code>head</code> and <code>shellComponent</code>:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">loader</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> ()</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> =&gt;</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> loadAuthState</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">(),</span></span>
<span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">shouldReload</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> false</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span></code></pre></div><h3 id="7-wrap-the-page" tabindex="-1">7. Wrap the page <a class="header-anchor" href="#7-wrap-the-page" aria-label="Permalink to &quot;7. Wrap the page&quot;">​</a></h3><p>In the same file, find the <code>&lt;body&gt;</code> in the root document. It renders <code>{children}</code>. Wrap that in <code>EvoAuthRoot</code>, and leave <code>&lt;Scripts /&gt;</code> after it:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&lt;</span><span style="--shiki-light:#9A4D00;--shiki-dark:#F0B65A;">EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&gt;{</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">children</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">}&lt;/</span><span style="--shiki-light:#9A4D00;--shiki-dark:#F0B65A;">EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&gt;</span></span></code></pre></div><h3 id="8-start-convex" tabindex="-1">8. Start Convex <a class="header-anchor" href="#8-start-convex" aria-label="Permalink to &quot;8. Start Convex&quot;">​</a></h3><p>In a second terminal, in <code>my-app</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>cd my-app</span></span>
<span class="line"><span>npx convex dev</span></span></code></pre></div><p>It pushes your <code>convex/</code> folder to the local deployment and keeps running. This is the terminal where the sign-up code appears.</p><h3 id="9-start-the-app" tabindex="-1">9. Start the app <a class="header-anchor" href="#9-start-the-app" aria-label="Permalink to &quot;9. Start the app&quot;">​</a></h3><p>In a third terminal, in <code>my-app</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>cd my-app</span></span>
<span class="line"><span>pnpm dev</span></span></code></pre></div><h3 id="10-sign-up" tabindex="-1">10. Sign up <a class="header-anchor" href="#10-sign-up" aria-label="Permalink to &quot;10. Sign up&quot;">​</a></h3><p>Open <code>http://localhost:3000/sign-up</code>. Enter an email address and a password of at least 15 characters that is not a well-known phrase (the form shows both rules: it refuses a password found in a known data breach), and press <strong>Create account</strong>. The page asks for a code and stays on the same page: leave it open. The terminal from step 8 has printed a message with the code: type it in on that page and press <strong>Create account</strong> again. The page then says <strong>You are signed in</strong>.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><ul><li><strong><code>init</code> says a file already exists.</strong> Move that file aside and run it again. <code>init</code> never overwrites or edits a file.</li><li><strong><code>init</code> says the env file is not ignored by git.</strong> Add <code>.env.local</code> to <code>.gitignore</code>, then run it again.</li><li><strong><code>init</code> says the <code>convex</code> package is missing.</strong> Run step 2, then step 3, then <code>init</code> again.</li><li><strong><code>init</code> could not set a variable on Convex.</strong> Fix the Convex error it printed. It names each variable that was not set, and the value is in <code>.env.local</code>.</li><li><strong>No code appears.</strong> The code is printed only by the terminal that runs <code>npx convex dev</code>, never the one that runs <code>pnpm dev</code>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./../convex.html">The Convex guide</a> and <a href="./../tanstack-start.html">the TanStack Start guide</a> explain the files <code>init</code> wrote.</li><li><a href="./../email-password.html">Email and password</a> covers password rules and reset.</li><li><a href="./../email.html">Email codes and links</a> shows how to replace the development sender before you deploy.</li><li><a href="./../github-oauth-app.html">Register a GitHub OAuth app</a> adds GitHub sign-in.</li></ul>`,42)])])}const k=a(n,[["render",i]]);export{u as __pageData,k as default};
